create  FUNCTION [dbo].[amar_froosh_mosh] (@hes nvarchar (50)) RETURNS Table  AS  RETURN ( SELECT     TOP 100 PERCENT SUM(dbo.INVO_LST.MEGHk) AS MEGHT, SUM(dbo.INVO_LST.MABL_K - dbo.INVO_LST.N_MOIN) AS MABL_K,dbo.Uday(dbo.HEAD_LST.DATE_N) AS DD, dbo.Umonth(dbo.HEAD_LST.DATE_N) AS mm, dbo.HEAD_LST.DATE_N, dbo.HEAD_LST.CUST_NO FROM         dbo.HEAD_LST INNER JOIN     dbo.INVO_LST ON dbo.HEAD_LST.NUMBER = dbo.INVO_LST.NUMBER AND dbo.HEAD_LST.TAG = dbo.INVO_LST.TAG WHERE     (dbo.HEAD_LST.TAG = 2) AND (dbo.HEAD_LST.CUST_NO = @hes) GROUP BY dbo.HEAD_LST.DATE_N, dbo.Uday(dbo.HEAD_LST.DATE_N), dbo.Umonth(dbo.HEAD_LST.DATE_N), dbo.HEAD_LST.CUST_NO ORDER BY dbo.HEAD_LST.DATE_N DESC)
